WITH v(slug, sw, fb, sh, sm, subs) AS (
  VALUES
  ('barbell-hip-thrust',
   'Start with the empty 45 lb bar and a pad. Hip thrusts get heavy fast, so most people add a 25 lb plate per side within a few sessions. You have it right when your hips lock out level with your knees and shoulders.',
   E'Sit on the floor with your upper back against a bench set at about knee height, roughly 16 inches.\n\nRoll the padded bar over your hips and plant your feet flat, shins vertical at the top of the rep.\n\nDrive through your heels and squeeze your glutes until your torso is parallel with the floor.\n\nTuck your chin and keep your ribs down so the movement stays in the hips.\n\nYou should feel this in the glutes. If it lands in your lower back, you are overextending at the top.\n\nMost common mistake: arching the lower back to reach lockout. Stop when your hips are level, not higher.',
   'If the hip thrust bench is taken',
   E'The Barbell Glute Bridge is the same movement from the floor, no bench needed, with a shorter range.\n\nThe Dumbbell Squat trains the glutes as part of a full squat pattern when nothing else is free.',
   ARRAY['barbell-glute-bridge','dumbbell-squat']),

  ('barbell-glute-bridge',
   'Start with the empty 45 lb bar. The range of motion is shorter than a hip thrust, so you can usually handle about 20% more weight once you have the pattern down.',
   E'Lie flat on the floor with knees bent and feet planted about hip-width, heels close to your glutes.\n\nRoll the padded bar over your hips and hold it with both hands.\n\nPush through your heels and lift your hips until your body forms a straight line from knees to shoulders.\n\nHold the top for one full count, then lower until your glutes tap the floor.\n\nYou should feel this in the glutes and hamstrings. Quad burn means your feet are too far forward.\n\nMost common mistake: pushing off the toes. Keep your weight in the heels and your shins vertical.',
   'If the barbell is in use',
   E'The Barbell Hip Thrust is the bench-elevated version with more range and more load potential.\n\nThe Single Leg Glute Bridge is bodyweight only, and one leg at a time makes it plenty hard.',
   ARRAY['barbell-hip-thrust','single-leg-glute-bridge']),

  ('parallel-bar-dip',
   'Bodyweight is the load. On the assisted dip machine, set the counterweight at about 40% of your bodyweight and take 10 lb off as you get stronger. Move to unassisted dips when you can do 12 reps with the counterweight under 20 lb.',
   E'Press up to a straight-arm hold and get stable before your first rep.\n\nPull your shoulders down away from your ears and hold them there.\n\nLower until your upper arms are parallel with the floor, elbows tracking back.\n\nPress up and stop just short of locking out.\n\nYou should feel this in the chest and triceps. Pain at the front of the shoulder means you went too deep.\n\nMost common mistake: dropping below parallel. Extra depth loads the shoulder joint and adds nothing.',
   'If the dip station is busy',
   E'Bench Dips are an easier entry point with your feet on the floor carrying part of the load.\n\nThe Close-Grip Barbell Bench Press is the same triceps and chest work lying down, with a load you set exactly.',
   ARRAY['bench-dips','close-grip-barbell-bench-press']),

  ('bench-dips',
   'Bodyweight with your knees bent and feet flat on the floor. Straighten your legs to make it harder, and put your heels on a second bench once that gets easy. Add a 10 lb plate on your lap only after 15 clean reps with straight legs.',
   E'Sit on the edge of a bench and grip it beside your hips, fingers pointing forward.\n\nSlide your hips forward off the bench, keeping them close to the edge the whole time.\n\nLower until your elbows reach 90 degrees, elbows pointing straight back.\n\nPress through your palms to lock out.\n\nYou should feel this in the triceps. Front-shoulder pinching means your hips drifted too far from the bench.\n\nMost common mistake: letting the hips travel forward, which forces the shoulders into deep extension. Stay within a few inches of the bench.',
   'If both benches are taken',
   E'The Parallel Bar Dip is the harder version with your full bodyweight on the arms.\n\nThe Reverse Grip Triceps Pushdown trains the same muscle at a load you control.',
   ARRAY['parallel-bar-dip','reverse-grip-triceps-pushdown']),

  ('chin-up',
   'Bodyweight. On the assisted machine, start with the counterweight at about half your bodyweight and lower it 10 lb at a time. A looped band over the bar works too. You are ready for unassisted chin-ups when 10 reps at 20 lb of assistance feel easy.',
   E'Hang from the bar with an underhand grip, hands about shoulder-width.\n\nPull your shoulder blades down first, before your arms bend.\n\nPull until your chin clears the bar, driving your elbows toward your ribs.\n\nLower all the way to straight arms under control.\n\nYou should feel this in the lats and biceps. If only your arms are working, you skipped the shoulder blade step.\n\nMost common mistake: cutting the bottom short and living in the top half of the rep. Full extension every time, even if the count drops.',
   'If the chin-up bar is occupied',
   E'The Inverted Row is a horizontal pull that builds the same base with less load on your arms.\n\nThe Close-Grip Front Lat Pulldown is a nearly identical pull pattern with the weight set on a stack.',
   ARRAY['inverted-row','close-grip-front-lat-pulldown']),

  ('inverted-row',
   'Bodyweight, and you adjust difficulty with the bar height. Set the bar at hip height to start, which puts you at roughly 45 degrees. Lower the bar to make it harder. You have it right when you can do 10 reps with your body in one straight line.',
   E'Set a barbell in a rack at hip height, or use a Smith machine.\n\nLie underneath and grip it just outside shoulder-width, arms straight.\n\nSqueeze your glutes and abs so your body holds a straight line from heels to head.\n\nPull your chest to the bar, driving your elbows back past your ribs.\n\nYou should feel this across the mid back. If your hips sag first, the abs gave out before the back did.\n\nMost common mistake: leading with the chin and letting the hips drop. The chest touches the bar, not the face.',
   'If the rack is in use',
   E'The Seated Machine Row is the same horizontal pull with your torso supported.\n\nThe Chin-Up is a vertical pull instead, and harder, but it trains the same muscles.',
   ARRAY['seated-machine-row','chin-up']),

  ('straight-arm-pulldown',
   'Start at 20 to 30 lb. Your arms stay straight the whole time, so the leverage is poor and the weight stays low. You have it right if you can pause at the bottom for a count without your torso folding forward.',
   E'Set the cable at the top of the tower with a straight bar or rope.\n\nStand a couple of feet back, hinge forward slightly at the hips, arms straight out in front.\n\nKeep a fixed soft bend in the elbows and push the bar down in an arc to your thighs.\n\nLet the bar rise back to eye level and feel the lats stretch.\n\nYou should feel this along the outside of your back, under the armpit. Triceps burn means your elbows are bending.\n\nMost common mistake: turning it into a pushdown by bending the arms. Lock the elbow angle before rep one.',
   'If the cable tower is busy',
   E'The Close-Grip Front Lat Pulldown is the same lat work with the arms allowed to bend, so you can load it heavier.\n\nThe Straight-Arm Dumbbell Pullover is a similar arc with a single dumbbell and a bench.',
   ARRAY['close-grip-front-lat-pulldown','straight-arm-dumbbell-pullover']),

  ('cable-crossover',
   'Start at 10 to 15 lb per side. Both stacks together add up faster than the number on one pin suggests. You have it right when you can bring your hands together in front of your chest and hold for a count without your elbows collapsing.',
   E'Set both pulleys at shoulder height or slightly above and take a handle in each hand.\n\nStep forward into a split stance so the cables have tension before you start.\n\nKeep a fixed 15-degree bend in the elbows and bring your hands together in front of your chest.\n\nLet the handles travel back until you feel a stretch across the chest, no further.\n\nYou should feel this across the chest and inner pec. Front-shoulder strain means you let the handles go too far back.\n\nMost common mistake: bending and straightening the elbows, which turns the fly into a press. The elbow angle never changes.',
   'If both cable stations are taken',
   E'Dumbbell Flyes are the free-weight version of the same arc, though the tension drops off at the top.\n\nThe Butterfly is the machine version with the path fixed, useful while you learn the movement.',
   ARRAY['dumbbell-flyes','butterfly']),

  ('preacher-curl',
   'Start with the empty EZ bar, which weighs 15 to 25 lb depending on your gym. The pad takes away all momentum, so this will feel heavier than a standing curl at the same weight. Add 5 lb per side once you hit 12 clean reps.',
   E'Set the seat so your armpits rest on the top of the pad with your feet flat.\n\nGrip the bar palms up, hands about shoulder-width, arms fully extended.\n\nCurl the bar up to chin height, keeping your upper arms flat on the pad.\n\nLower slowly all the way to straight arms. This bottom half is where the growth happens.\n\nYou should feel this in the lower biceps near the elbow. Elbow ache means you dropped the weight instead of lowering it.\n\nMost common mistake: cutting the bottom of the rep short. Full extension every time, even with less weight on the bar.',
   'If the preacher bench is taken',
   E'The Alternate Hammer Curl is a standing option that adds forearm work.\n\nCable Hammer Curls with a rope keep constant tension, which makes cheating harder.',
   ARRAY['alternate-hammer-curl','cable-hammer-curls-rope-attachment']),

  ('alternate-hammer-curl',
   'Start with 10 to 15 lb dumbbells. Alternating means one arm rests while the other works, so you can go about 5 lb heavier per hand than a strict two-arm curl. You have it right if your elbows stay pinned to your sides for all 10 reps per arm.',
   E'Stand with a dumbbell in each hand, palms facing your thighs.\n\nPress your upper arms against your ribs and keep them there.\n\nCurl one dumbbell to shoulder height without turning the wrist, then lower it fully before starting the other side.\n\nKeep the resting arm hanging straight rather than half-curled.\n\nYou should feel this in the biceps and the top of the forearm.\n\nMost common mistake: rocking the torso to start each rep. Stand with your back against a wall for one set and you will feel exactly how much you were swinging.',
   'If the dumbbell rack is picked over',
   E'Cable Hammer Curls with a rope use the same neutral grip with steady tension.\n\nThe Preacher Curl removes momentum completely by fixing your upper arms in place.',
   ARRAY['cable-hammer-curls-rope-attachment','preacher-curl']),

  ('cable-hammer-curls-rope-attachment',
   'Start at 20 to 30 lb. Cables hold tension through the whole range, so a weight that feels light in the first two reps often stops being light by rep eight. You have it right if the last rep looks like the first.',
   E'Clip a rope to the low pulley and take one end in each hand, palms facing each other.\n\nStand about a foot back from the stack so the cable stays tight at the bottom.\n\nCurl the rope up toward your shoulders, keeping your elbows locked at your sides.\n\nLower for a count of 2 until your arms are straight.\n\nYou should feel this in the biceps and forearms, with no break in tension at the bottom.\n\nMost common mistake: stepping too close to the stack, which lets the weight rest at the bottom of each rep. Back up until you feel pull with your arms straight.',
   'If the cable stack is busy',
   E'The Alternate Hammer Curl is the same grip with dumbbells.\n\nThe Preacher Curl is a different angle and the strictest form of the three.',
   ARRAY['alternate-hammer-curl','preacher-curl']),

  ('reverse-grip-triceps-pushdown',
   'Start at 15 to 25 lb, which is lighter than a rope pushdown. The underhand grip is weaker and your wrists will complain before your triceps do if you load it up. You have it right if you can do 12 reps standing upright with your elbows still.',
   E'Attach a straight bar to the high pulley and grip it palms up, hands shoulder-width.\n\nStand close to the stack with elbows tucked against your ribs and a slight forward lean.\n\nPush the bar down until your arms are straight, wrists neutral.\n\nLet your hands rise until your forearms pass parallel with the floor.\n\nYou should feel this in the inner and lower triceps near the elbow.\n\nMost common mistake: the elbows drifting forward and away from the ribs, which hands the work to the shoulders. If the elbows move, take weight off.',
   'If the cable station is occupied',
   E'Bench Dips are bodyweight triceps work that needs nothing but a bench.\n\nThe Standing Dumbbell Triceps Extension trains the long head overhead, which pushdowns mostly miss.',
   ARRAY['bench-dips','standing-dumbbell-triceps-extension']),

  ('barbell-shrug',
   'Start with the empty 45 lb bar and add a 25 lb plate per side once the movement feels stable. The range is short and traps are strong, so this climbs quickly. Grip usually fails before the traps do, so use straps past 135 lb.',
   E'Stand holding the bar in front of your thighs, hands just outside your hips, arms straight.\n\nSet your feet hip-width and stand tall with your chin level.\n\nRaise your shoulders straight up toward your ears.\n\nHold the top for one count, then lower slowly and let the traps stretch.\n\nYou should feel this across the top of the shoulders and up the neck.\n\nMost common mistake: rolling the shoulders backward in a circle. Shrugs travel straight up and straight down. Rolling adds joint wear and no extra work.',
   'If the barbell is in use',
   E'The Dumbbell Shrug is the same movement, and the neutral hand position is easier on the wrists.\n\nThe Farmer''s Walk loads the traps and grip together while you walk.',
   ARRAY['dumbbell-shrug','farmers-walk']),

  ('standing-dumbbell-upright-row',
   'Start with 10 to 15 lb dumbbells. This one goes wrong under heavy load more than most, so keep it light and stop the set when form slips. You have it right if you can stop at chest height with your elbows above your hands.',
   E'Stand with a dumbbell in each hand, palms facing your thighs, arms straight.\n\nPull the dumbbells straight up close to your body, leading with the elbows.\n\nStop when your hands reach chest height and your elbows are level with your shoulders.\n\nLower under control to straight arms.\n\nYou should feel this in the side delts and traps. Pinching inside the shoulder means you pulled too high.\n\nMost common mistake: pulling all the way to the chin. Stop at chest height. The last few inches are where shoulders get irritated.',
   'If the dumbbells you want are gone',
   E'The Side Lateral Raise hits the side delts with less shoulder rotation, so it is the safer option.\n\nThe Barbell Shrug trains the trap half of the movement with heavier load.',
   ARRAY['side-lateral-raise','barbell-shrug']),

  ('cable-rear-delt-fly',
   'Start with the lightest plate on each side, usually 10 to 15 lb. Rear delts are small and most beginners have never trained them directly, so the number stays low for a while. You have it right if you feel it behind the shoulder and not in your traps.',
   E'Set both pulleys at shoulder height and cross the cables, taking the left handle in your right hand and the right in your left.\n\nStand in the middle with a slight bend in your elbows, arms crossed in front of your chest.\n\nPull your arms out and back in a wide arc until they are level with your torso.\n\nHold for one count, then return slowly.\n\nYou should feel this across the back of the shoulders.\n\nMost common mistake: shrugging as you pull, which moves the work to the traps. Pull your shoulder blades down before the first rep.',
   'If the cable station is taken',
   E'The Seated Bent-Over Rear Delt Raise is the dumbbell version of the same arc.\n\nThe Face Pull hits the same target muscles plus the rotator cuff.',
   ARRAY['seated-bent-over-rear-delt-raise','face-pull']),

  ('seated-bent-over-rear-delt-raise',
   'Start with 5 to 10 lb dumbbells. Almost everyone picks up too much here and turns it into a row. You have it right when you can hold the top position for a full second with your arms nearly straight.',
   E'Sit on the end of a bench with your feet flat and lean your chest toward your thighs.\n\nLet the dumbbells hang under your knees, palms facing each other, elbows barely bent.\n\nRaise your arms out to the sides until they are level with your shoulders.\n\nLower slowly, keeping your chest down against your thighs the whole time.\n\nYou should feel this behind the shoulders. Mid-back squeeze means your elbows bent and it became a row.\n\nMost common mistake: sitting up as the set gets hard. Keep your chest on your thighs. If you cannot, the weight is too heavy.',
   'If the light dumbbells are all gone',
   E'The Cable Rear Delt Fly has steadier tension and is easier to load in small jumps.\n\nThe Face Pull is a cable option that trains the same area from a different angle.',
   ARRAY['cable-rear-delt-fly','face-pull']),

  ('hack-squat',
   'Start with the empty sled, which runs 60 to 100 lb depending on the machine, then add a 25 lb plate per side. The back pad supports you, so most people move up faster here than on a free-weight squat. You have it right when you can reach parallel with your heels flat.',
   E'Set your feet shoulder-width in the middle of the platform, back and hips flat against the pad.\n\nUnrack the sled and take a breath before you descend.\n\nLower until your thighs are level with the platform, knees tracking over your toes.\n\nDrive through your whole foot to stand back up, stopping short of locking the knees.\n\nYou should feel this in the quads.\n\nMost common mistake: placing the feet too low on the platform, which pushes the knees far past the toes and loads the joint. Move your feet up an inch or two if your knees ache.',
   'If the hack squat is taken',
   E'The Split Squat with Dumbbells works one leg at a time, so far less total load is needed.\n\nThe Leg Press is a similar supported squat pattern with a different back angle.',
   ARRAY['split-squat-with-dumbbells','leg-press']),

  ('split-squat-with-dumbbells',
   'Bodyweight for the first week while you sort out balance, then 15 to 20 lb dumbbells. Both feet stay on the floor here, which makes it easier than a Bulgarian split squat. You have it right when you can lower to a knee tap without wobbling.',
   E'Step one foot forward about 2 feet and hold that stance for the whole set.\n\nHold a dumbbell in each hand at your sides, chest tall.\n\nLower straight down until your back knee nearly touches the floor.\n\nPush through your front heel to stand, keeping the front foot flat.\n\nYou should feel this in the front-leg quad and glute.\n\nMost common mistake: drifting forward and pushing off the back toe. The rear leg balances, the front leg lifts. Weight stays in the front heel.',
   'If you need a smaller step',
   E'The Hack Squat is a machine option with no balance demand at all.\n\nThe Dumbbell Squat works both legs together, which is easier to hold steady while you build up.',
   ARRAY['hack-squat','dumbbell-squat']),

  ('good-morning',
   'Start with a 15 to 30 lb training bar, not the 45 lb barbell. This lift punishes a rounded back and there is no reason to rush the load. Move to the empty 45 lb bar once you can do 10 reps with a flat back and no knee change.',
   E'Set the bar on your upper back like a squat, hands wide, feet hip-width.\n\nSoften the knees slightly and keep that same bend for every rep.\n\nPush your hips straight back and let your chest travel toward the floor.\n\nStop when your torso reaches about 45 degrees or your hamstrings stop you, whichever comes first.\n\nYou should feel a strong stretch in the hamstrings. Lower-back strain means your back rounded.\n\nMost common mistake: bending at the waist instead of the hips. Practice with your back 6 inches from a wall and touch the wall with your hips on every rep.',
   'If you want the same work with less risk',
   E'The Stiff-Legged Dumbbell Deadlift is the same hinge with the load in your hands, which is easier to bail out of.\n\nHyperextensions are a bodyweight hinge with your torso supported.',
   ARRAY['stiff-legged-dumbbell-deadlift','hyperextensions-back-extensions']),

  ('sumo-deadlift',
   'Load 95 lb, the 45 lb bar plus a 25 lb plate per side. Use plates that stand 17 to 18 inches tall so the bar starts at the right height. If 95 lb is too much, use bumper plates or blocks rather than smaller plates on the floor.',
   E'Set your feet wide, toes turned out about 40 degrees, shins close to the bar.\n\nGrip inside your knees, arms straight and vertical.\n\nDrop your hips, lift your chest, and pull the slack out of the bar before you move it.\n\nPush the floor away with both feet and stand up, keeping the bar against your legs.\n\nYou should feel this in the glutes, quads, and inner thighs.\n\nMost common mistake: yanking the bar off the floor with a soft back. Take the slack out first. The bar should make a quiet click before it moves.',
   'If the platform is taken',
   E'The Barbell Hip Thrust trains the same glute drive with no spinal load.\n\nThe Leg Press covers the leg work while you wait for the bar.',
   ARRAY['barbell-hip-thrust','leg-press']),

  ('seated-calf-raise',
   'Start with 45 lb, one plate on the machine. Seated calf raises train the soleus with the knee bent, so the weight is much lower than a standing raise. You have it right when you can pause at the top for a count and still get 15 reps.',
   E'Sit with the balls of your feet on the platform and the pad snug across your lower thighs.\n\nRelease the safety and let your heels drop as far as they go.\n\nPush through the balls of your feet and raise your heels as high as possible.\n\nHold the top for a full count, then lower slowly and hold the stretch for a beat.\n\nYou should feel this low in the calf, near the Achilles.\n\nMost common mistake: fast, bouncy half reps that use the tendon instead of the muscle. Slow down and take the full range both directions.',
   'If the seated machine is in use',
   E'Standing Calf Raises use straight legs, which shifts the work to the gastrocnemius, so the weight will be higher.\n\nThe Farmer''s Walk loads the calves along with grip and traps.',
   ARRAY['standing-calf-raises','farmers-walk']),

  ('farmers-walk',
   'Start with 25 to 35 lb dumbbells in each hand and walk 40 yards, or about 30 seconds. Grip is the limit for most beginners. Add weight when you can finish the walk without setting the dumbbells down.',
   E'Deadlift the dumbbells off the floor with a flat back rather than bending at the waist.\n\nStand tall with your shoulders pulled back and down, arms hanging straight.\n\nTake short quick steps and keep your ribs down so you do not lean.\n\nSet the weights down under control at the end. Do not drop them.\n\nYou should feel this in your grip, traps, and abs.\n\nMost common mistake: leaning back to counterbalance the load. Brace your abs and stay upright. If you cannot, the weight is too heavy.',
   'If you have no clear floor space',
   E'The Barbell Shrug trains the traps in one spot with heavier load.\n\nThe Dumbbell Shrug is the same idea and easier to grab from the rack.',
   ARRAY['barbell-shrug','dumbbell-shrug']),

  ('cable-crunch',
   'Start at 30 to 40 lb. You need enough weight to anchor your upper body, so going too light makes the movement awkward. You have it right if you can round your spine and reach your elbows toward your knees without your hips moving.',
   E'Set a rope on the high pulley and kneel a couple of feet back from the stack.\n\nHold the rope beside your ears and hinge slightly forward to load the cable.\n\nCrunch by rounding your spine and bringing your ribs toward your hips.\n\nReturn slowly until you feel your abs stretch, keeping tension the whole time.\n\nYou should feel this in the abs. Hip flexor or lower back work means you bent at the hips.\n\nMost common mistake: pulling with the arms and rocking at the hips. Your hands stay glued beside your head and your hips stay still. Only your spine moves.',
   'If the cable tower is busy',
   E'The Russian Twist is bodyweight ab work that adds rotation.\n\nThe Hanging Leg Raise trains the lower abs from the other end.',
   ARRAY['russian-twist','hanging-leg-raise']),

  ('russian-twist',
   'Bodyweight with your hands clasped, feet on the floor. Add a 5 to 10 lb plate or dumbbell once you can do 20 controlled twists. Lifting the feet makes it harder than adding weight does, so try that first.',
   E'Sit with your knees bent and lean back until your torso is about 45 degrees from the floor.\n\nHold your hands together in front of your chest and keep your chest tall.\n\nRotate your shoulders and ribs to one side, pause, then rotate to the other.\n\nMove slowly. Two seconds per side is a reasonable pace.\n\nYou should feel this in the obliques and deep abs.\n\nMost common mistake: swinging the arms side to side while the torso stays still. The rotation comes from your ribs, not your hands. Slow down until you feel it.',
   'If your lower back rounds',
   E'The Cable Crunch is loaded ab work with your spine supported by the kneeling position.\n\nThe Plank trains the same area with no spinal rotation, which is kinder on the lower back.',
   ARRAY['cable-crunch','plank'])
)
INSERT INTO public.beginner_notes
  (exercise_id, starting_weight_md, form_breakdown_md, substitution_heading, substitution_md, substitute_exercise_ids)
SELECT e.id, v.sw, v.fb, v.sh, v.sm,
       ARRAY(SELECT s.id FROM unnest(v.subs) WITH ORDINALITY AS t(slug, ord)
             JOIN public.exercises s ON s.slug = t.slug ORDER BY t.ord)
FROM v JOIN public.exercises e ON e.slug = v.slug
ON CONFLICT (exercise_id) DO UPDATE SET
  starting_weight_md = EXCLUDED.starting_weight_md,
  form_breakdown_md = EXCLUDED.form_breakdown_md,
  substitution_heading = EXCLUDED.substitution_heading,
  substitution_md = EXCLUDED.substitution_md,
  substitute_exercise_ids = EXCLUDED.substitute_exercise_ids;